public static void main(String[] args) {
    Scanner scan = new Scanner(System.in);
    int n = scan.nextInt();
    int maxSize = 1;
    for (int i = 0; i < n; i++) {
        maxSize *= 3;
    }
    char[][] result = new char[maxSize][maxSize];

    extendCarpet(0, 0, maxSize, result);

    for (int j = 0; j < result.length; j++) {
        for (int i = 0; i < result.length; i++) {
            System.out.print(result[j][i]);
        }
        System.out.println();
    }

    scan.close();
}

private static void extendCarpet(int x, int y, int size, char[][] result) {
    if (size == 1) {
        result[x][y] = '#';
        return;
    }

    int newSize = size / 3;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (i == 1 && j == 1) {
                for (int dx = 0; dx < newSize; dx++) {
                    for (int dy = 0; dy < newSize; dy++) {
                        result[x + i * newSize + dx][y + j * newSize + dy] = ' ';
                    }
                }
            } else {
                extendCarpet(x + i * newSize, y + j * newSize, newSize, result);
            }
        }
    }
}
